program='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    up = down = 0
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    p = (y + dy, x + dx)
                    if 0 <= p[0] < h and 0 <= p[1] < w and grid[p[0]][p[1]] == 2 and p not in seen:
                        seen.add(p)
                        q.append(p)
            minr, maxr = min(y for y, x in cells), max(y for y, x in cells)
            # An upright T has its single stem cell above the three-cell bar.
            if sum(y == minr for y, x in cells) == 1:
                up += 1
            else:
                down += 1
    out = [[0] * 6 for _ in range(3)]
    slots = ((0, 0), (2, 0), (0, 2), (2, 2))
    for color, count, offset in ((3, up, 0), (1, down, 3)):
        for y, x in slots[:count]:
            out[y][x + offset] = color
    return out
'''
